export type Link = { label: string; href: string };
/** 一个工具在某页里的样子;没写的字段用 vendors.ts 的默认值 */
export type ToolPick = {
  key: string;
  /** 一句「最适合谁」 */
  bestFor: string;
  /** 覆盖 vendors.ts 的一句话定义(BuzzVideo 在不同品类讲不同的工具) */
  what?: string;
  strengths?: string[];
  cautions?: string[];
  /** 覆盖入门价 / 免费额度(BuzzVideo 在音频页讲 Seed Audio 1.0) */
  entry?: string;
  free?: string;
  /** 站内入口(BuzzVideo 的工具页) */
  tryHref?: string;
};
export type Row = { label: string; bv: string; them: string };
export type MediaKind = "ads" | "ugc" | "avatar" | "video" | "image" | "audio";

export type AltPage = {
  slug: string;
  /** vendors.ts 的 key */
  them: string;
  h1: string;
  lead: string;
  answer: string;
  /** 「怎么选」:每条一句标题 + 一句说明 */
  choose: { title: string; body: string }[];
  h2h: Row[];
  /** 竞品比 BuzzVideo 强的地方(必须写) */
  themStronger: string[];
  /** BuzzVideo 不一样的地方 */
  bvDifferent: string[];
  /** 速览表 + 逐个工具;第一个永远是 buzzvideo,第二个是被比较的竞品 */
  tools: ToolPick[];
  faq: { q: string; a: string }[];
  related: Link[];
  media: MediaKind;
  cta: Link;
};

export type BestPage = {
  slug: string;
  h1: string;
  lead: string;
  answer: string;
  criteria: string[];
  tools: ToolPick[];
  faq: { q: string; a: string }[];
  related: Link[];
  media: MediaKind;
  cta: Link;
  /** 模型榜：多一张 BuzzVideo 模型规格表 */
  modelTable?: string[];
};

